<?php require 'config.php';require_admin();$period=$_GET['period']??'month';$format=$period==='day'?'%Y-%m-%d':($period==='year'?'%Y':'%Y-%m');$s=$pdo->prepare("SELECT DATE_FORMAT(created_at,?) period,COUNT(*) orders_count,SUM(total) revenue FROM orders WHERE status<>'Cancelled' GROUP BY period ORDER BY period DESC LIMIT 24");$s->execute([$format]);$rows=$s->fetchAll();$sold=$pdo->query("SELECT product_name,SUM(quantity) qty,SUM(quantity*unit_price) revenue FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status<>'Cancelled' GROUP BY product_id,product_name ORDER BY qty DESC LIMIT 20")->fetchAll();$page_title='Sales reports';require 'header.php';?><div class="adminnav"><a href="admin.php">Dashboard</a><a href="admin_products.php">Products & stock</a><a href="admin_orders.php">Orders</a><a href="admin_messages.php">Messages</a><a href="admin_reports.php">Sales reports</a></div><section class="wrap"><h1>Sales reports</h1><p><a class="btn" href="?period=day">Daily</a> <a class="btn" href="?period=month">Monthly</a> <a class="btn" href="?period=year">Yearly</a></p><h2>Revenue by <?=e($period)?></h2><table class="table"><tr><th>Period</th><th>Orders</th><th>Revenue</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['period'])?></td><td><?=$r['orders_count']?></td><td><?=money($r['revenue'])?></td></tr><?php endforeach;?></table><h2>Best-selling products</h2><table class="table"><tr><th>Product</th><th>Units sold</th><th>Revenue</th></tr><?php foreach($sold as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=$r['qty']?></td><td><?=money($r['revenue'])?></td></tr><?php endforeach;?></table></section><?php require 'footer.php';?>
